func call(_ request: Request) async throws -> Reply {
    try await withThrowingTaskGroup(of: Reply.self) { group in
        group.addTask { try await transport.send(request) }
        group.addTask {
            try await Task.sleep(for: .seconds(5))
            throw CallError.timeout
        }
        defer { group.cancelAll() }          // cancel the loser
        return try await group.next()!       // first result wins
    }
}
